def categorize_time(value):
    match = re.match(r'(\d{1,2}):\d{2}(?: [AP]M)?', value)
    if match:
        hour = int(match.group(1))
        if 0 <= hour < 13:
            return "%s" % ({hour}:00 A.M.)
        else:
            return "%s" % ({hour-12}:00 P.M.)
    else:
        return value

